/bin/bash -lc "npx -y -p playwright node - <<'NODE'
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1440, height: 980 } });
  const errors = [];
  page.on('pageerror', err => errors.push(err.message));
  page.on('console', msg => {
    if (msg.type() === 'error') errors.push(msg.text());
  });
  await page.goto('http://127.0.0.1:4173/index.html', { waitUntil: 'domcontentloaded' });
  await page.waitForFunction(() => document.querySelector('#scenarioBody tr') && document.querySelector('#latestMetric').textContent "'!== '"'--', null, { timeout: 20000 });
  const status = await page.locator('#statusText').innerText();
  const latest = await page.locator('#latestMetric').innerText();
  const forecastBefore = await page.locator('#forecastMetric').innerText();
  await page.locator('#modelSelect').selectOption('ewma');
  await page.locator('#horizonRange').evaluate(el => { el.value = 126; el.dispatchEvent(new Event('input', { bubbles: true })); });
  await page.locator('#confidenceSelect').selectOption('0.95');
  await page.waitForTimeout(250);
  const horizon = await page.locator('#horizonLabel').innerText();
  const confidence = await page.locator('#confidenceLabel').innerText();
  const model = await page.locator('#modelLabel').innerText();
  const forecastAfter = await page.locator('#forecastMetric').innerText();
  const rows = await page.locator('#scenarioBody tr').count();
  const canvasCheck = await page.locator('#chart').evaluate(canvas => {
    const ctx = canvas.getContext('2d');
    const { width, height } = canvas;
    const data = ctx.getImageData(0, 0, width, height).data;
    let nonWhite = 0;
    for (let i = 0; i < data.length; i += 4) {
      if ("'!(data[i] > 248 && data[i + 1] > 248 && data[i + 2] > 248) && data[i + 3] > 0) nonWhite++;
    }
    return { width, height, nonWhite };
  });
  await page.screenshot({ path: '"'dashboard-desktop.png', fullPage: true });
  await page.setViewportSize({ width: 390, height: 900 });
  await page.waitForTimeout(250);
  const mobileOverlapCheck = await page.evaluate(() => {
    const body = document.body.getBoundingClientRect();
    const header = document.querySelector('header').getBoundingClientRect();
    const chart = document.querySelector('#chart').getBoundingClientRect();
    return {
      bodyWidth: body.width,
      headerWidth: header.width,
      chartWidth: chart.width,
      horizontalOverflow: document.documentElement.scrollWidth > document.documentElement.clientWidth + 1
    };
  });
  await page.screenshot({ path: 'dashboard-mobile.png', fullPage: true });
  await browser.close();
  if (errors.length) throw new Error('Browser errors: ' + errors.join(' | '));
  if (rows < 5) throw new Error('Expected at least 5 scenario rows, found ' + rows);
  if (canvasCheck.nonWhite < 1000) throw new Error('Canvas appears blank: ' + JSON.stringify(canvasCheck));
  if (mobileOverlapCheck.horizontalOverflow) throw new Error('Mobile layout has horizontal overflow: ' + JSON.stringify(mobileOverlapCheck));
  console.log(JSON.stringify({ status, latest, forecastBefore, model, horizon, confidence, forecastAfter, rows, canvasCheck, mobileOverlapCheck }, null, 2));
})();
NODE"

